/**
 * Tiny i18n: the Portuguese text IS the key. English and Spanish tables live in ./i18n/{en,es}.json
 * (generated by scripts/i18n/extract.mjs + translated, reviewed by hand). Missing keys fall back to Portuguese.
 * The language is chosen on the start screen and saved on the device; changing it reloads the page so every
 * canvas texture is rebuilt in the new language.
 */
import en from './i18n/en.json'
import es from './i18n/es.json'

export type Lang = 'pt' | 'en' | 'es'
export const LANGS: { id: Lang; label: string; flag: string }[] = [
  { id: 'pt', label: 'Português', flag: 'PT' },
  { id: 'en', label: 'English', flag: 'EN' },
  { id: 'es', label: 'Español', flag: 'ES' },
]
const KEY = 'encaixe-lang'
const TABLES: Record<Exclude<Lang, 'pt'>, Record<string, string>> = { en, es }

function detect(): Lang {
  try {
    const saved = localStorage.getItem(KEY)
    if (saved === 'pt' || saved === 'en' || saved === 'es') return saved
  } catch { /* ignore */ }
  const nav = (typeof navigator !== 'undefined' ? navigator.language : 'pt').toLowerCase()
  // Portuguese by default (many Quests in Brazil are set to English); Spanish devices start in Spanish.
  return nav.startsWith('es') ? 'es' : 'pt'
}

export let lang: Lang = detect()

export function setLang(next: Lang): void {
  try { localStorage.setItem(KEY, next) } catch { /* ignore */ }
  lang = next
}

/** Translate a Portuguese string; {name} placeholders are filled from params. */
export function t(pt: string, params?: Record<string, string | number>): string {
  let out = lang === 'pt' ? pt : (TABLES[lang][pt] ?? pt)
  if (params) for (const [k, v] of Object.entries(params)) out = out.split(`{${k}}`).join(String(v))
  return out
}

/** Translate every string field of the data tables in place (call once at boot, before building scenes). */
export function translateData<T extends object>(table: T, fields: string[]): void {
  if (lang === 'pt') return
  for (const item of Object.values(table) as Record<string, unknown>[]) {
    for (const f of fields) if (typeof item[f] === 'string') item[f] = t(item[f] as string)
  }
}
